46. 
47. public class TemplateParser {
48. 
49.   private static final String VERSION_DEVELOP = "develop";
50.   private static final String VERSION_LATEST = "latest";
51.   private static final String DATA_DOCS_VERSION = "docsVersion";
52.   private static final String DATA_OPERATONBPM_VERSION = "operatonbpmVersion";
53. 
54.   public static void main(String[] args) throws IOException, TemplateException {
55. 
56.     if (args.length != 4) {
57.       throw new RuntimeException(
58.           "Must provide four arguments: "
59.           + "<source template directory> "
60.           + "<main template> "
61.           + "<output directory> "
62.           + "<intermediate output dir>");
63.     }
64. 
65.     String sourceDirectory = args[0];
66.     String mainTemplate = args[1];
67.     String outputFile = args[2];
68.     String debugFile = args[3];
69. 
70.     Configuration cfg = new Configuration(Configuration.VERSION_2_3_29);
71. 
72.     cfg.setDirectoryForTemplateLoading(new File(sourceDirectory));
73.     cfg.setDefaultEncoding(UTF_8.name());
74. 
75.     Template template = cfg.getTemplate(mainTemplate);
76. 
77.     Map<String, Object> templateData = createTemplateData(sourceDirectory);
78. 
79.     try (StringWriter out = new StringWriter()) {
80. 
81.       template.process(templateData, out);
82. 
83.       // create intermediate json file before the formatting
84.       String path = createOutputFile(debugFile);
85.       FileUtils.forceMkdir(new File(debugFile));
86.       Files.write(Path.of(path), out.getBuffer().toString().getBytes());
87. 
88.       // format json with Gson
89.       String jsonString = out.getBuffer().toString();
90.       String formattedJson = formatJsonString(jsonString);
91. 
92.       File outFile = new File(outputFile);
93.       FileUtils.forceMkdir(outFile.getParentFile());
94.       Files.write(outFile.toPath(), formattedJson.getBytes());
95.     }
96. 
97.   }
98. 
99.   protected static Map<String, Object> createTemplateData(String sourceDirectory) {
100.     Map<String, Object> templateData = new HashMap<>();
101. 
102.     resolveVersions(templateData);
103.     Map<String, String> models = resolveModels(sourceDirectory);
104.     templateData.put("models", models);
105.     Map<String, List<String>> endpoints = resolvePaths(sourceDirectory);
106.     templateData.put("endpoints", endpoints);
107. 
108.     return templateData;
109.   }
110. 
111.   protected static String formatJsonString(String jsonString) {
112.     Gson gson = new GsonBuilder()
113.         .serializeNulls()
114.         .setPrettyPrinting()
115.         .create();
116. 
117.     JsonElement json = JsonParser.parseString(jsonString);
118.     return gson.toJson(json);
119.   }
120. 
121.   protected static String createOutputFile(String debugFile) {
122.     DateTimeFormatter timeStampPattern = DateTimeFormatter.ofPattern("MM-dd-HH-mm-ss");
123. 
124.     return debugFile + "/intermediate-openapi-"
125.         + timeStampPattern.format(java.time.LocalDateTime.now()) + ".json";
126.   }
127. 
128.   /**
129.    * Resolve the Operaton version and the respective documentation version used in the links.
130.    */
131.   protected static void resolveVersions(Map<String, Object> templateData) {
132.     String version = TemplateParser.class.getPackage().getImplementationVersion();
133. 
134.     if (version != null) {
135.       // operatonbpmVersion = 7.X.Y
136.       templateData.put(DATA_OPERATONBPM_VERSION, version);
137. 
138.       if (version.contains("SNAPSHOT")) {
139.         templateData.put(DATA_DOCS_VERSION, VERSION_DEVELOP);
140.       } else if (version.contains("alpha")) {
141.         templateData.put(DATA_DOCS_VERSION, VERSION_LATEST);
142.       } else {
143.         // docsVersion = 7.X
144.         templateData.put(DATA_DOCS_VERSION, version.substring(0, version.lastIndexOf(".")));
145.       }
146.     } else {
147.       // only for debug cases
148.       templateData.put(DATA_OPERATONBPM_VERSION, VERSION_DEVELOP);
149.       templateData.put(DATA_DOCS_VERSION, VERSION_DEVELOP);
150.     }
151.   }
152. 
153.   /**
154.    *
155.    * @param sourceDirectory the template directory that stores the models
156.    * @return a map of model name and file path to it,
157.    * the map is ordered lexicographically by the model names
158.    */
159.   protected static Map<String, String> resolveModels(String sourceDirectory) {
160.     File modelsDir = new File(sourceDirectory + "/models");
161.     Collection<File> modelFiles = FileUtils.listFiles(
162.         modelsDir,
163.         new RegexFileFilter("^(.*?)"),
164.         DirectoryFileFilter.DIRECTORY
165.     );
166. 
167.     Map<String, String> models = new TreeMap<>();
168.     for (File file : modelFiles) {
169.       String modelName = FilenameUtils.removeExtension(file.getName());
170.       String filePath = file.getAbsolutePath();
171.       String modelPackage = filePath
172.           .substring(filePath.lastIndexOf("org"), filePath.lastIndexOf(File.separator));
173. 
174.       models.put(modelName, modelPackage);
175.     }
176. 
177.     return models;
178.   }
179. 
180.   /**
181.    *
182.    * @param sourceDirectory the template directory that stores the endpoints
183.    * @return a map of endpoint path and HTTP methods pairs,
184.    * the map is ordered lexicographically by the endpoint paths
185.    * the list of methods is ordered as well
186.    */
187.   protected static Map<String, List<String>> resolvePaths(String sourceDirectory) {
188.     File endpointsDir = new File(sourceDirectory + "/paths");
189.     int endpointStartAt = endpointsDir.getAbsolutePath().length();
190.     Collection<File> endpointsFiles = FileUtils.listFiles(
191.         endpointsDir,
192.         new RegexFileFilter("^(.*?)"),
193.         DirectoryFileFilter.DIRECTORY
194.     );
195. 
196.     Map<String, List<String>> endpoints = new TreeMap<>();
197.     for (File file : endpointsFiles) {
198.       String endpointMethod = FilenameUtils.removeExtension(file.getName());
199.       String filePath = file.getAbsolutePath();
200.       String endpointPath = filePath
201.           .substring(endpointStartAt, filePath.lastIndexOf(File.separator))
202.           .replace(File.separator, "/");
203. 
204.       List<String> operations;
205.       if (endpoints.containsKey(endpointPath)) {
206.         operations = endpoints.get(endpointPath);
207.         operations.add(endpointMethod);
208.       } else {
209.         operations = new ArrayList<>();
210.         operations.add(endpointMethod);
211.         endpoints.put(endpointPath, operations);
212.       }
213. 
214.       if(operations.size() > 1) {
215.         Collections.sort(operations);
216.       }
217.     }
218. 
219.     return endpoints;
220.   }
221. 
222. }
