package org.operaton.bpm.engine.rest.openapi.generator.impl;

import java.io.File;
import java.io.IOException;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.networknt.schema.Error;
import com.networknt.schema.Schema;
import com.networknt.schema.SchemaRegistry;
import com.networknt.schema.SpecificationVersion;

/**
 * Validates a JSON document against a JSON schema using the
 * <a href="https://github.com/networknt/json-schema-validator">networknt json-schema-validator</a>.
 *
 * <p>The schema is interpreted according to the JSON Schema Draft 4 specification, which is the
 * dialect used by the bundled OpenAPI 3.0 schema.</p>
 *
 * <p>This class is used during the build to validate the generated {@code openapi.json} against the
 * OpenAPI 3.0 schema. The build fails when the generated document does not conform to the schema.</p>
 */
public class SchemaValidator {

  private static final ObjectMapper MAPPER = new ObjectMapper();

  private SchemaValidator() {
  }

  /**
   * Validates the given input file against the given JSON schema and fails the build when the input
   * does not conform to the schema.
   *
   * @param args two arguments are expected: the path to the JSON schema and the path to the file to
   *          validate
   * @throws IOException if the schema or the input file cannot be read
   * @throws RuntimeException if the number of arguments is not two or if the input file does not
   *           conform to the schema
   */
  public static void main(String[] args) throws IOException {
    if (args.length != 2) {
      throw new RuntimeException("Must provide two arguments: <json schema> <file to validate>");
    }

    String jsonSchemaPath = args[0];
    String inputFile = args[1];

    Set<String> errors = validate(new File(jsonSchemaPath), new File(inputFile));

    if (!errors.isEmpty()) {
      String messages = String.join("\n", errors);
      throw new RuntimeException("Schema validation errors\n" + messages);
    }
  }

  /**
   * Validates the given input file against the given JSON schema.
   *
   * @param jsonSchema the JSON schema file, interpreted as JSON Schema Draft 4
   * @param inputFile the file to validate against the schema
   * @return the set of validation error messages, or an empty set when the input conforms to the
   *         schema
   * @throws IOException if the schema or the input file cannot be read
   */
  protected static Set<String> validate(File jsonSchema, File inputFile) throws IOException {
    JsonNode schemaNode = MAPPER.readTree(jsonSchema);
    JsonNode inputNode = MAPPER.readTree(inputFile);

    SchemaRegistry registry = SchemaRegistry.withDefaultDialect(SpecificationVersion.DRAFT_4);
    Schema schema = registry.getSchema(schemaNode);

    List<Error> errors = schema.validate(inputNode);

    return errors.stream()
        .map(Error::getMessage)
        .collect(Collectors.toSet());
  }
}

